export const buildOptions = (task: Task, hooks: Options["hooks"], store: SessionStore): Options => {
  const route = routeFor(task.job); // Opus 5.5 at medium unless the plan picked another row
  return {
    model: route.model,
    effort: route.effort,
    cwd: "/work/fcp", // the same on every VM, so a stored session resumes anywhere
    settingSources: ["project"], // fcp's own CLAUDE.md, AGENTS.md and .claude/ settings
    allowedTools: ["Read", "Grep", "Glob", "Edit", "Write", "Bash", "TodoWrite", "Workflow",
      "mcp__nova__ask_human", "mcp__nova__post_progress", "mcp__nova__kb_search"],
    disallowedTools: ["WebFetch", "WebSearch"], // the proxy blocks the web anyway; say so up front
    permissionMode: "dontAsk", // nobody sits at a prompt: anything not allowed is refused
    mcpServers: { nova: createSdkMcpServer({ name: "nova", tools: [askHuman, postProgress, kbSearch] }) },
    hooks, // the walls, next section
    sessionStore: store, // the transcript leaves the VM, last section
    resume: task.resumeSessionId,
    pathToClaudeCodeExecutable: "/usr/local/bin/claude", // the pinned binary the nightly smoke test passed
    env: {
      ...process.env, // env REPLACES the environment, so keep PATH, HOME and the proxy settings
      ANTHROPIC_BASE_URL: GATEWAY_URL, // our gateway over PrivateLink, never api.anthropic.com
      ANTHROPIC_AUTH_TOKEN: task.gatewayToken, // the run token: not a key, dies with the run
      ENABLE_TOOL_SEARCH: "true", // off by default behind a gateway
      CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH: "1", // helpers can't start helpers
    },
    // No maxTurns, no maxBudgetUsd, no taskBudget: work is never cut off mid-run.
  };
};

const PROTECTED = loadGlobs("/opt/ai-agents/harness/settings/protected-paths.yaml"); // the locked-checks list
const NEVER_RUN =
  /\b(terraform|tofu|terragrunt)\b.*\b(apply|destroy)\b|argocd\s+app\s+sync|gh\s+workflow\s+run|\/dispatches\b|169\.254\.169\.254/;

export const blockWalls: HookCallback = async (input) => {
  const { tool_name: tool, tool_input } = input as PreToolUseHookInput;
  const args = tool_input as { file_path?: string; notebook_path?: string; command?: string };
  const path = args.file_path ?? args.notebook_path;
  if (path && matches(path, PROTECTED)) {
    return refuse(tool, path, "This file is one of the checks your work is judged by. " +
      "Add a new test instead, or ask the requester with ask_human.");
  }
  if (tool === "Bash" && args.command && NEVER_RUN.test(args.command)) {
    return refuse(tool, args.command, "Agents never apply, destroy, sync or dispatch. Leave a note for a person.");
  }
  return {};
};

const refuse = (tool: string, target: string, why: string): HookJSONOutput => {
  ledger.refused(tool, target, why); // /run/nova/refusals.jsonl, listed in the PR
  return { hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: why } };
};

export class BrokerS3SessionStore implements SessionStore {
  readonly #seen = new Set<string>(); // entry uuids already stored
  #seq = 0;
  constructor(private readonly broker: BrokerClient) {}

  async append(key: SessionKey, entries: SessionStoreEntry[]): Promise<void> {
    const fresh = entries.filter((e) => !(typeof e.uuid === "string" && this.#seen.has(e.uuid)));
    if (fresh.length === 0) return;
    const name = `${this.#prefix(key)}/part-${Date.now()}-${String(this.#seq++).padStart(6, "0")}.jsonl`;
    const url = await this.broker.artifactUrl(name, { write: true }); // presigned, this run's folder only
    const res = await fetch(url, { method: "PUT", body: fresh.map((e) => JSON.stringify(e)).join("\n") });
    if (!res.ok) throw new Error(`session store PUT failed: ${res.status}`); // the SDK retries
    for (const e of fresh) if (typeof e.uuid === "string") this.#seen.add(e.uuid);
  }
  // load(key): list the parts in name order (= time order), download each, parse the lines
}

