// A small copy of nova-worker's session setup: one function turns the task into options.
import { query, type HookCallback, type Options, type PreToolUseHookInput } from "@anthropic-ai/claude-agent-sdk";
import { appendFile } from "node:fs/promises";
import { resolve } from "node:path";

const PROTECTED = ["/.github/workflows/"]; // in the platform: settings/protected-paths.yaml
const NEVER_RUN = /\b(terraform|tofu|terragrunt)\b.*\b(apply|destroy)\b|argocd\s+app\s+sync|gh\s+workflow\s+run|\/dispatches\b|169\.254\.169\.254/;
const refusals: { tool: string; target: string; why: string }[] = []; // the refusal ledger

const refuse = (tool: string, target: string, why: string) => {
  refusals.push({ tool, target, why });
  return { hookSpecificOutput: { hookEventName: "PreToolUse" as const, permissionDecision: "deny" as const, permissionDecisionReason: why } };
};

const blockWalls: HookCallback = async (input) => {
  const { tool_name, tool_input } = input as PreToolUseHookInput;
  const { file_path: path, command } = tool_input as { file_path?: string; command?: string };
  if (path && PROTECTED.some((p) => path.includes(p))) {
    return refuse(tool_name, path, "This file is one of the checks your work is judged by. Add a new test instead, or ask the requester.");
  }
  if (tool_name === "Bash" && command && NEVER_RUN.test(command)) {
    return refuse(tool_name, command, "Agents never apply, destroy, sync or dispatch. Leave a note for a person.");
  }
  return {};
};

const buildOptions = (task: { cwd: string; runToken: string }): Options => ({
  cwd: task.cwd,
  model: "claude-opus-5-5",
  tools: ["Read", "Grep", "Glob", "Edit", "Write", "Bash"],
  allowedTools: ["Read", "Grep", "Glob", "Edit", "Write", "Bash"],
  permissionMode: "dontAsk",
  settingSources: [],
  hooks: { PreToolUse: [{ matcher: "Edit|Write|NotebookEdit|Bash", hooks: [blockWalls] }] },
  env: {
    ...process.env, // env replaces the whole environment, so keep PATH and HOME
    ANTHROPIC_BASE_URL: process.env.GATEWAY_URL ?? "http://localhost:8787",
    ANTHROPIC_AUTH_TOKEN: task.runToken, // a run token, not an Anthropic key
  },
  // no maxTurns, no maxBudgetUsd, no taskBudget
});

const task = { cwd: resolve("work"), runToken: "run-RH-1234-7f3a" };
for await (const msg of query({ prompt: "Make CI green for RH-1234.", options: buildOptions(task) })) {
  if (msg.type === "result") console.log(`session ended: ${msg.subtype}, last words: ${"result" in msg ? msg.result : ""}`);
}
console.log("refusal ledger:", JSON.stringify(refusals, null, 1));
if (refusals.length) await appendFile("refusals.jsonl", refusals.map((r) => JSON.stringify(r)).join("\n") + "\n");
